18	// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
19	// the detail endpoint returns, so a huge file cannot bloat a response.
20	const maxDocBytes = 128 * 1024
21	
22	// apiServer holds the request-independent state for the JSON API.
23	type apiServer struct {
24		root    string
25		version string
26		topo    topologyProvider
27	
28		// topoMu guards the cached provider result. Fetching runs the hosts'
29		// graph verbs (a dotnet build on first run), so the result is computed
30		// once — on the first /api/topology request — and reused until an
31		// explicit refresh.
32		topoMu      sync.Mutex
33		topoLoaded  bool
34		topoEntries []topology.Entry
35		topoErrs    []string
36	}
