38	// topologyReport is the /api/topology payload: every declared topology plus
39	// the per-host failures the UI renders. Topologies is always an array (never
40	// null) even when empty.
41	type topologyReport struct {
42		Topologies []topologyEntry `json:"topologies"`
43		Errors     []string        `json:"errors,omitempty"`
44	}
45	
46	// topologyEntry is one system's declared topology plus the authored
47	// enrichment read from its directory: message descriptions keyed by connector
48	// name. The docs ride beside the Topology rather than inside it — the
49	// topology stays exactly what the host declared.
50	type topologyEntry struct {
51		topology.Entry
52		MessageDocs map[string]messageDoc `json:"messageDocs,omitempty"`
53	}
