61	// integrationSummary is a scaffold entry plus the coordinates the sidebar
62	// tree groups by: Name is the directory that carries the .intropy record.
63	// System is the name a sibling system-host scaffold declares for the
64	// directory's parent, falling back to the parent folder's name; Domain is the
65	// system's parent folder. Absent a host, System is empty when the integration
66	// sits directly under the workspace root, and Domain is empty when the
67	// system does.
68	type integrationSummary struct {
69		template.ScaffoldEntry
70		Name   string `json:"name"`
71		System string `json:"system,omitempty"`
72		Domain string `json:"domain,omitempty"`
73	}
