86	// newHandler wires the API routes and the SPA static handler onto a mux.
87	func newHandler(root, version string, topo topologyProvider) (http.Handler, error) {
88		api := &apiServer{root: root, version: version, topo: topo}
89		static, err := staticHandler()
90		if err != nil {
91			return nil, err
92		}
93	
94		mux := http.NewServeMux()
95		mux.HandleFunc("GET /api/health", api.health)
96		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
97		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
98		mux.HandleFunc("GET /api/flow", api.flow)
99		mux.HandleFunc("GET /api/topology", api.topologies)
100		mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
101		mux.Handle("/", static)
102		return mux, nil
103	}
