112	// listIntegrations mirrors `int list -o json` — the same scaffold entries in
113	// the same order — with the derived name/system fields added on top and each
114	// Path normalized to a root-relative identifier. The response is always an
115	// array (never null) even when empty.
116	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
117		entries, systems := s.scan()
118		summaries := make([]integrationSummary, 0, len(entries))
119		for _, e := range entries {
120			summaries = append(summaries, s.summarize(e, systems))
121		}
122		writeJSON(w, http.StatusOK, summaries)
123	}
124	
125	// scan splits the workspace's scaffold entries for the API: the integration
126	// blocks to catalog, plus the declared systems keyed by their root directory
127	// (the directory holding a system-host scaffold). Support projects — the host
128	// and its shared contracts library — are infrastructure the system view
129	// already represents, not integrations to list.
130	func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
131		entries, _ := template.ListScaffolds(s.root)
132		systems = map[string]string{}
133		for _, e := range entries {
134			if e.Role == template.RoleSystemHost {
135				systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
136			}
137		}
138		blocks = entries[:0]
139		for _, e := range entries {
140			if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
141				continue
142			}
143			blocks = append(blocks, e)
144		}
145		return blocks, systems
146	}
