148	// systemName is the name a system-host scaffold declares for its system
149	// (the template's `name` value, recorded at `sys create`), falling back to
150	// the host's parent directory name.
151	func systemName(host template.ScaffoldEntry) string {
152		if name, ok := host.Values["name"].(string); ok && name != "" {
153			return name
154		}
155		dir := filepath.Dir(host.Path)
156		if abs, err := filepath.Abs(dir); err == nil {
157			dir = abs
158		}
159		return filepath.Base(dir)
160	}
161	
162	// summarize derives an entry's tree coordinates from its path and the
163	// declared systems. A sibling system-host makes membership explicit: its
164	// declared name wins over the folder-derived one and applies even directly
165	// under the workspace root (where no folder-derived system exists).
166	// Otherwise the workspace root itself never counts as a system or domain, so
167	// an integration scaffolded at the root has neither and one directly under
168	// the root has a system but no domain. The served Path is made root-relative
169	// so it is a stable, URL-safe identifier regardless of whether the command
170	// was given a relative or absolute root (an absolute path would otherwise
171	// break detail lookups).
172	func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
173		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
174		sum.Path = s.relPath(e.Path)
175		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
176		parent := filepath.Dir(path)
177		if declared, ok := systems[parent]; ok && path != root {
178			sum.System = declared
179			if grand := filepath.Dir(parent); parent != root && grand != root {
180				sum.Domain = filepath.Base(grand)
181			}
182			return sum
183		}
184		if path == root || parent == root {
185			return sum
186		}
187		sum.System = filepath.Base(parent)
188		if grand := filepath.Dir(parent); grand != root {
189			sum.Domain = filepath.Base(grand)
190		}
191		return sum
192	}
193	
194	// relPath turns an entry's on-disk path into the root-relative, slash-separated
195	// identifier used in API responses and URLs. It falls back to the cleaned path
196	// so a value is always produced even if Rel fails (e.g. differing volumes).
197	func (s *apiServer) relPath(p string) string {
198		if rel, err := filepath.Rel(s.root, p); err == nil {
199			return filepath.ToSlash(rel)
200		}
201		return filepath.ToSlash(filepath.Clean(p))
202	}
