204	// flow returns every integration enriched with the pipeline steps and Dapr
205	// components the flow canvas draws, so the whole graph loads in one request.
206	// It reuses integrationDetail but leaves the document fields (agents/readme)
207	// nil — the canvas nodes do not render them.
208	func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
209		entries, systems := s.scan()
210		nodes := make([]integrationDetail, 0, len(entries))
211		for _, e := range entries {
212			dir := e.Path
213			nodes = append(nodes, integrationDetail{
214				integrationSummary: s.summarize(e, systems),
215				Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
216				PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
217			})
218		}
219		writeJSON(w, http.StatusOK, nodes)
220	}
