222	// topologies returns every system topology declared by a host's graph verb,
223	// each Path normalized to the same root-relative identifier integration
224	// paths use, so the flow canvas can match a topology to the integrations
225	// living beside its host. The provider result is cached after the first
226	// request (the verb builds the host); POST /api/topology/refresh recomputes.
227	func (s *apiServer) topologies(w http.ResponseWriter, r *http.Request) {
228		writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), false))
229	}
230	
231	// refreshTopologies recomputes the topology cache by re-running every host's
232	// graph verb, then returns the fresh report.
233	func (s *apiServer) refreshTopologies(w http.ResponseWriter, r *http.Request) {
234		writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), true))
235	}
236	
237	// topologyReport assembles the /api/topology payload: the cached provider
238	// result plus the message docs read fresh from disk on every request, so an
239	// edited doc shows up on a browser refresh without re-running the hosts'
240	// graph verbs.
241	func (s *apiServer) topologyReport(ctx context.Context, force bool) topologyReport {
242		entries, errs := s.cachedTopologies(ctx, force)
243		report := topologyReport{
244			Topologies: make([]topologyEntry, 0, len(entries)),
245			Errors:     append([]string(nil), errs...),
246		}
247		for _, e := range entries {
248			docs, docErrs := s.messageDocs(e)
249			report.Topologies = append(report.Topologies, topologyEntry{Entry: e, MessageDocs: docs})
250			report.Errors = append(report.Errors, docErrs...)
251		}
252		return report
253	}
254	
255	// cachedTopologies returns the provider result — computed on first use or
256	// when force is set, reused otherwise. Concurrent requests share one
257	// computation. Entry paths are normalized to root-relative identifiers.
258	func (s *apiServer) cachedTopologies(ctx context.Context, force bool) ([]topology.Entry, []string) {
259		s.topoMu.Lock()
260		defer s.topoMu.Unlock()
261		if !s.topoLoaded || force {
262			entries, errs := s.topo(ctx)
263			s.topoEntries = make([]topology.Entry, 0, len(entries))
264			for _, e := range entries {
265				e.Path = s.relPath(e.Path)
266				s.topoEntries = append(s.topoEntries, e)
267			}
268			s.topoErrs, s.topoLoaded = errs, true
269		}
270		return s.topoEntries, s.topoErrs
271	}
272	
273	// messageDocs reads the authored connector payload descriptions beside a
274	// system, keyed by connector name. A doc naming a connector the topology does
275	// not declare is surfaced as an error and withheld — never guessed around.
276	// Error messages carry the doc's workspace-relative path.
277	func (s *apiServer) messageDocs(e topology.Entry) (map[string]messageDoc, []string) {
278		docs, errs := readMessageDocs(filepath.Join(s.root, filepath.FromSlash(e.Path)))
279		prefix := ""
280		if e.Path != "." {
281			prefix = e.Path + "/"
282		}
283		for i, msg := range errs {
284			errs[i] = prefix + msg
285		}
286		known := map[string]bool{}
287		for _, c := range e.Connectors {
288			known[c.Name] = true
289		}
290		var unknown []string
291		for name := range docs {
292			if !known[name] {
293				unknown = append(unknown, name)
294				delete(docs, name)
295			}
296		}
297		sort.Strings(unknown)
298		for _, name := range unknown {
299			errs = append(errs, fmt.Sprintf("%s%s/%s.md: no connector %q declared by system %q",
300				prefix, messagesDirName, name, name, e.System))
301		}
302		if len(docs) == 0 {
303			docs = nil
304		}
305		return docs, errs
306	}
