308	func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
309		want := strings.Trim(r.PathValue("path"), "/")
310		// An integration at the workspace root has the identifier "." (see
311		// relPath), but a browser strips the "." segment from /api/integrations/.
312		// so it arrives empty — treat the two as the same request.
313		if want == "" {
314			want = "."
315		}
316		entries, systems := s.scan()
317		for _, e := range entries {
318			if s.relPath(e.Path) == want {
319				writeJSON(w, http.StatusOK, s.enrich(e, systems))
320				return
321			}
322		}
323		writeError(w, http.StatusNotFound, "integration not found: "+want)
324	}
