326	// enrich reads optional on-disk context for an integration. The entry's Path
327	// is already usable from the process working directory (see ListScaffolds), so
328	// it doubles as the project directory.
329	func (s *apiServer) enrich(e template.ScaffoldEntry, systems map[string]string) integrationDetail {
330		dir := e.Path
331		return integrationDetail{
332			integrationSummary: s.summarize(e, systems),
333			Agents:             readDoc(dir, "AGENTS.md"),
334			Readme:             readDoc(dir, "README.md"),
335			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
336			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
337		}
338	}
339	
340	// readDoc returns the named text file's (possibly truncated) contents, or nil
341	// if it is absent or unreadable.
342	func readDoc(dir, name string) *fileDoc {
343		data, err := os.ReadFile(filepath.Join(dir, name))
344		if err != nil {
345			return nil
346		}
347		if len(data) > maxDocBytes {
348			data = data[:maxDocBytes]
349		}
350		return &fileDoc{Name: name, Content: string(data)}
351	}
352	
353	// listNames returns the sorted base names of the files directly under dir, or
354	// nil if dir is absent or unreadable.
355	func listNames(dir string) []string {
356		ents, err := os.ReadDir(dir)
357		if err != nil {
358			return nil
359		}
360		var names []string
361		for _, ent := range ents {
362			if !ent.IsDir() {
363				names = append(names, ent.Name())
364			}
365		}
366		sort.Strings(names)
367		return names
368	}
