150	// observeArgo fills in the sync and health of each row, in place.
151	//
152	// Unreachable ArgoCD is a warning rather than a failure, unlike sync and diff
153	// where there is no command at all without the API call. Everything to the left
154	// of those two columns was read from git and is still true; refusing to print
155	// the digests because the cluster is unreachable would withhold most of the
156	// answer over part of it.
157	func observeArgo(ctx context.Context, repo *gitops.Repository, deployCfg *gitops.DeployConfig, s *session, opts StatusOptions, rows []EnvironmentStatus) {
158		client, creds, err := connect(deployCfg, opts.ArgocdServer, s.argocdServer, opts.UserAgent)
159		if err != nil {
160			fmt.Fprintf(opts.Stderr, "warning: not reading sync or health from ArgoCD: %v\n", err)
161			return
162		}
163		fmt.Fprintf(opts.Stderr, "reading %d application(s) from %s\n", len(rows), creds.Server)
164	
165		for i := range rows {
166			app, err := client.Get(ctx, rows[i].AppName)
167			if err != nil {
168				if errors.Is(err, argocd.ErrUnreachable) {
169					// The server is down or the token is stale. Every remaining
170					// request would fail the same way, so stop asking.
171					fmt.Fprintf(opts.Stderr, "warning: %v\n", err)
172					return
173				}
174				// A single unknown application: the component is onboarded in git
175				// but its Application does not exist, or not under this namespace.
176				// The other rows are unaffected.
177				fmt.Fprintf(opts.Stderr, "warning: %s: %v\n", rows[i].AppName, err)
178				continue
179			}
180	
181			rows[i].SyncStatus = app.Status.Sync.Status
182			rows[i].HealthStatus = app.Status.Health.Status
183			rows[i].SyncedRevision = app.Status.Sync.Revision
184	
185			// Pending is a git question, not an ArgoCD one: has the commit that
186			// last changed this overlay reached the cluster? A descendant counts,
187			// which is why this is revisionContains rather than an equality test.
188			if rows[i].Revision != "" {
189				applied, err := revisionContains(repo)(ctx, rows[i].Revision, app.Status.Sync.Revision)
190				if err == nil {
191					rows[i].Pending = !applied
192				}
193			}
194		}
195	}
