197	// pinSignature is an environment's digests, in declared image order.
198	//
199	// Empty when the overlay does not pin a digest for every image — there is then
200	// no set of bits to compare, which is a different thing from disagreeing about
201	// one.
202	func pinSignature(row EnvironmentStatus) string {
203		if !row.Onboarded || len(row.Pins) == 0 {
204			return ""
205		}
206		digests := make([]string, 0, len(row.Pins))
207		for _, pin := range row.Pins {
208			if pin.Digest == "" {
209				return ""
210			}
211			digests = append(digests, pin.Digest)
212		}
213		return strings.Join(digests, " ")
214	}
215	
216	// consistent reports whether every onboarded environment pins the identical
217	// digest for every image.
218	//
219	// An environment that pins no digest makes the answer false rather than being
220	// skipped: the claim is "everything agrees", and an environment nobody can
221	// compare has not been shown to agree with anything.
222	func consistent(rows []EnvironmentStatus) bool {
223		signature, seen := "", false
224		for _, row := range rows {
225			if !row.Onboarded {
226				continue
227			}
228			s := pinSignature(row)
229			if s == "" {
230				return false
231			}
232			if seen && s != signature {
233				return false
234			}
235			signature, seen = s, true
236		}
237		return seen
238	}
