15	// PlaceholderPrefix marks a value only a human can supply — a connection string,
16	// a host, a credential, a cron schedule.
17	//
18	// The spelling is load-bearing. It contains no YAML metacharacter, so it is a
19	// legal unquoted plain scalar in every position including the start of a value;
20	// it is legal inside a URL; the hint after the prefix says what to supply, so a
21	// grep hit is self-explanatory; and one regexp finds every instance.
22	const PlaceholderPrefix = "REPLACE-ME-"
23	
24	// A hint of at least one character, ending in an alphanumeric so trailing
25	// punctuation in prose ("set REPLACE-ME-SFTP-HOST, then …") is not swallowed.
26	var placeholderPattern = regexp.MustCompile(`REPLACE-ME-[A-Z0-9-]*[A-Z0-9]`)
27	
28	// Placeholder is one unfilled value in one line of one file.
29	type Placeholder struct {
30		// File is relative to the scanned root, slash-separated.
31		File string `json:"file"`
32		Line int    `json:"line"`
33	
34		// Token is the whole marker including its hint, so a reader knows what the
35		// value is without opening the file.
36		Token string `json:"token"`
37	}
38	
39	// scanPlaceholders reports every placeholder in rels, which are slash-separated
40	// paths relative to root.
41	//
42	// A path that does not exist is skipped rather than an error: the same function
43	// serves --plan, where it scans a staging directory, and a re-run, where it scans
44	// the committed tree and some of rels were never written.
45	//
46	// An unpinned image tag is deliberately *not* a placeholder. Pinning is
47	// intropy deploy's job, and inviting someone to hand-edit an image tag would
48	// undo the digest discipline the rest of this package exists to enforce.
